typedef struct { uint8_t input[131072];size_t input_count,input_offset,read_limit;uint8_t output[262144];size_t output_count,write_limit,write_calls,write_fail_after;int write_mode,read_mode,install_count,uninstall_count,locks;bool install_fail,uninstall_fail;atomic_uint_fast64_t now_ms;pthread_mutex_t mutex; } fake_t;
static esp_err_t install(void*c){fake_t*f=c;++f->install_count;return f->install_fail?ESP_FAIL:ESP_OK;}static esp_err_t uninstall(void*c){fake_t*f=c;++f->uninstall_count;return f->uninstall_fail?ESP_FAIL:ESP_OK;}static int readf(void*c,uint8_t*b,size_t cap,uint32_t t){(void)t;fake_t*f=c;if(f->read_mode<0)return-1;if(f->read_mode>0)return(int)cap+1;size_t n=f->input_count-f->input_offset;if(n>cap)n=cap;if(f->read_limit&&n>f->read_limit)n=f->read_limit;memcpy(b,f->input+f->input_offset,n);f->input_offset+=n;return(int)n;}static int writef(void*c,const uint8_t*b,size_t n,uint32_t t){(void)t;fake_t*f=c;++f->write_calls;if(f->write_fail_after&&f->write_calls>=f->write_fail_after)return-1;if(f->write_mode<0)return-1;if(f->write_mode==1)return 0;if(f->write_mode==2)return(int)n+1;if(f->write_limit&&n>f->write_limit)n=f->write_limit;assert(f->output_count+n<=sizeof(f->output));memcpy(f->output+f->output_count,b,n);f->output_count+=n;return(int)n;}static uint64_t now(void*c){return atomic_load(&((fake_t*)c)->now_ms);}static void lock(void*c){fake_t*f=c;pthread_mutex_lock(&f->mutex);++f->locks;}static void unlock(void*c){fake_t*f=c;--f->locks;pthread_mutex_unlock(&f->mutex);}
static vk_usb_service_t*make_policy(fake_t*f,bool enabled){assert(pthread_mutex_init(&f->mutex,NULL)==0);vk_usb_service_t*s=calloc(1,vk_usb_service_size());assert(s);vk_usb_transport_ops_t o={install,uninstall,readf,writef,now,lock,unlock,f};vk_usb_identity_t i={"vibe_keyboard","test","VS-TEST"};vk_usb_service_policy_t p={.update_boot_policy_enabled=enabled};assert(vk_usb_service_init(s,&o,&i,&p)==ESP_OK);return s;}static vk_usb_service_t*make(fake_t*f){return make_policy(f,false);}static void bytes(fake_t*f,const uint8_t*b,size_t n){assert(f->input_count+n<=sizeof(f->input));memcpy(f->input+f->input_count,b,n);f->input_count+=n;}static void frame_t(fake_t*f,uint8_t type,const uint8_t*b,size_t n){uint8_t h[]={1,type,(uint8_t)n,(uint8_t)(n>>8)};bytes(f,h,4);bytes(f,b,n);}static void frame(fake_t*f,const char*j){frame_t(f,0x10,(const uint8_t*)j,strlen(j));}static void poll(vk_usb_service_t*s){assert(vk_usb_service_poll(s)==ESP_OK);}static void all(vk_usb_service_t*s,fake_t*f){size_t g=0;do{poll(s);assert(++g<200000);}while(f->input_offset<f->input_count);}static bool contains(fake_t*f,const char*t){size_t n=strlen(t);for(size_t i=0;i+n<=f->output_count;++i)if(memcmp(f->output+i,t,n)==0)return true;return false;}static void reset_in(fake_t*f){f->input_count=f->input_offset=0;}static void epoch(vk_usb_service_t*s,fake_t*f){frame(f,"{\"event\":\"transport\",\"kind\":\"usb\"}");all(s,f);assert(vk_usb_service_has_epoch(s));}

static void test_unicode(void){const char*bad[]={"{\"event\":\"ping\\u0000x\"}","{\"event\":\"transport\",\"kind\":\"usb\\u0000x\"}","{\"event\":\"ui_state\",\"state\":\"ready\\u0000x\",\"text\":\"x\"}","{\"event\\u0000x\":\"ping\"}","{\"event\":\"vk_asset_begin\",\"transfer_id\":1,\"sha256\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\",\"total_bytes\":1,\"kind\":\"image\\u0000x\"}","{\"event\":\"\\uD800\"}","{\"event\":\"\\uDC00\"}"};static const uint8_t raw0[]={'{','"','e','v','e','n','t','"',':','"',0,'"','}'};static const uint8_t high[]={ '{','"','e','v','e','n','t','"',':','"',0xf4,0x90,0x80,0x80,'"','}' };fake_t f={0};vk_usb_service_t*s=make(&f);assert(vk_usb_service_start(s)==ESP_OK);for(size_t i=0;i<sizeof(bad)/sizeof(*bad);++i)frame(&f,bad[i]);frame_t(&f,0x10,raw0,sizeof(raw0));frame_t(&f,0x10,high,sizeof(high));frame(&f,"{\"event\":\"transport\",\"kind\":\"us\\u0062\"}");all(s,&f);assert(vk_usb_service_has_epoch(s));reset_in(&f);frame(&f,"{\"event\":\"ui_state\",\"state\":\"ready\",\"text\":\"\\uD83D\\uDE00\"}");all(s,&f);assert(vk_usb_service_stop(s)==ESP_OK);free(s);}

static int provider_calls;static fake_t*provider_fake;static vk_usb_capability_snapshot_t provider_snapshot;static esp_err_t provider_result;
static esp_err_t capability_provider(void*c,uint32_t epoch,vk_usb_capability_snapshot_t*out){(void)c;assert(epoch!=0U);assert(provider_fake==NULL||provider_fake->locks==0);++provider_calls;if(provider_result==ESP_OK)*out=provider_snapshot;return provider_result;}
static void register_provider(vk_usb_service_t*s){vk_usb_capability_provider_registration_t r={capability_provider,NULL};assert(vk_usb_service_register_capability_provider(s,&r)==ESP_OK);}
static int input_commands;static vk_usb_input_command_t last_input_command;
static esp_err_t on_input_command(void*c,const vk_usb_input_command_t*x){(void)c;++input_commands;last_input_command=*x;return ESP_OK;}
static int commands,chunks;static esp_err_t command_result=ESP_OK,chunk_result=ESP_OK;static vk_usb_asset_command_t last_cmd;static vk_usb_asset_chunk_t last_chunk;static esp_err_t oncmd(void*c,const vk_usb_asset_command_t*x){(void)c;++commands;last_cmd=*x;return command_result;}static esp_err_t onchunk(void*c,const vk_usb_asset_chunk_t*x){(void)c;++chunks;last_chunk=*x;return chunk_result;}
static int update_commands,update_chunks;static vk_usb_update_command_t last_update_cmd;static vk_usb_update_chunk_t last_update_chunk;static bool tuple_available=true;static esp_err_t on_update_cmd(void*c,const vk_usb_update_command_t*x){(void)c;++update_commands;last_update_cmd=*x;return ESP_OK;}static esp_err_t on_update_chunk(void*c,const vk_usb_update_chunk_t*x){(void)c;++update_chunks;last_update_chunk=*x;return ESP_OK;}static bool update_tuple(void*c){(void)c;return tuple_available;}static void register_update_rejected(vk_usb_service_t*s){vk_usb_update_handler_registration_t r={on_update_cmd,on_update_chunk,update_tuple,NULL,4,10};assert(vk_usb_service_register_update_handler(s,&r)==ESP_ERR_NOT_SUPPORTED);}
static void register_asset(vk_usb_service_t*s){vk_usb_asset_handler_registration_t r={.handle_command=oncmd,.handle_chunk=onchunk,.context=NULL,.chunk_bytes=4,.max_asset_bytes=1000,.get_transfer_state=NULL};assert(vk_usb_service_register_asset_handler(s,&r)==ESP_OK);provider_snapshot=(vk_usb_capability_snapshot_t){0};provider_snapshot.assets=(vk_usb_assets_capability_t){.state=VK_USB_CAPABILITY_AVAILABLE,.storage_state=VK_USB_STORAGE_READY,.free_bytes=2000,.reserve_bytes=1,.upload_max_bytes=1000,.max_asset_bytes=1000,.chunk_bytes=4,.max_assets=1,.max_frames=1,.min_frame_ms=1,.max_frame_ms=1,.max_active_decoded_bytes=1,.decoder_scratch_bytes=1};provider_result=ESP_OK;register_provider(s);}
static void authorize(vk_usb_service_t*s,fake_t*f){reset_in(f);frame(f,"{\"event\":\"get_device_info\"}");all(s,f);reset_in(f);f->output_count=0;}

typedef struct { pthread_mutex_t mutex; pthread_cond_t condition; bool entered; bool release; bool alive; } provider_gate_t;
static esp_err_t blocking_provider(void *context,uint32_t epoch,vk_usb_capability_snapshot_t *snapshot)
{
    provider_gate_t *gate=context;assert(epoch!=0U);assert(pthread_mutex_lock(&gate->mutex)==0);
    assert(gate->alive);gate->entered=true;assert(pthread_cond_broadcast(&gate->condition)==0);
    while(!gate->release)assert(pthread_cond_wait(&gate->condition,&gate->mutex)==0);
    assert(gate->alive);assert(pthread_mutex_unlock(&gate->mutex)==0);*snapshot=(vk_usb_capability_snapshot_t){0};return ESP_OK;
}
typedef struct { vk_usb_service_t *service; fake_t *fake; esp_err_t result; } provider_refresh_t;
static void *refresh_provider(void *context)
{
    provider_refresh_t *refresh=context;reset_in(refresh->fake);frame(refresh->fake,"{\"event\":\"get_device_info\"}");
    refresh->result=vk_usb_service_poll(refresh->service);return NULL;
}
static void test_provider_lifetime_stop(void)
{
    fake_t f={0};provider_gate_t gate={.mutex=PTHREAD_MUTEX_INITIALIZER,.condition=PTHREAD_COND_INITIALIZER,.alive=true};
    vk_usb_service_t *service=make(&f);vk_usb_capability_provider_registration_t registration={blocking_provider,&gate};
    assert(vk_usb_service_register_capability_provider(service,&registration)==ESP_OK);assert(vk_usb_service_start(service)==ESP_OK);epoch(service,&f);
    provider_refresh_t refresh={service,&f,ESP_OK};pthread_t thread;assert(pthread_create(&thread,NULL,refresh_provider,&refresh)==0);
    assert(pthread_mutex_lock(&gate.mutex)==0);while(!gate.entered)assert(pthread_cond_wait(&gate.condition,&gate.mutex)==0);assert(pthread_mutex_unlock(&gate.mutex)==0);
    assert(vk_usb_service_stop(service)==ESP_ERR_TIMEOUT);assert(f.uninstall_count==0);
    assert(pthread_mutex_lock(&gate.mutex)==0);gate.release=true;assert(pthread_cond_broadcast(&gate.condition)==0);assert(pthread_mutex_unlock(&gate.mutex)==0);
    assert(pthread_join(thread,NULL)==0);assert(refresh.result==ESP_ERR_INVALID_STATE);
    assert(pthread_mutex_lock(&gate.mutex)==0);gate.alive=false;assert(pthread_mutex_unlock(&gate.mutex)==0);
    assert(vk_usb_service_stop(service)==ESP_OK);assert(f.uninstall_count==1);free(service);
}

static void test_capability_provider(void){
    fake_t f={0};provider_fake=&f;provider_calls=0;provider_result=ESP_OK;provider_snapshot=(vk_usb_capability_snapshot_t){0};
    provider_snapshot.update.state=VK_USB_CAPABILITY_UNAVAILABLE;provider_snapshot.update.unavailable_reason=VK_USB_UPDATE_REASON_BOOTLOADER_MIGRATION_REQUIRED;
    vk_usb_service_t*s=make(&f);register_provider(s);assert(vk_usb_service_start(s)==ESP_OK);epoch(s,&f);reset_in(&f);f.output_count=0;frame(&f,"{\"event\":\"get_device_info\"}");all(s,&f);assert(provider_calls==1);assert(contains(&f,"bootloader_migration_required"));
    provider_snapshot=(vk_usb_capability_snapshot_t){0};reset_in(&f);f.output_count=0;frame(&f,"{\"event\":\"get_device_info\"}");all(s,&f);assert(provider_calls==2);assert(!contains(&f,"bootloader_migration_required"));assert(contains(&f,"\"features\":{}"));
    provider_result=ESP_FAIL;provider_snapshot.update.state=VK_USB_CAPABILITY_UNAVAILABLE;reset_in(&f);f.output_count=0;frame(&f,"{\"event\":\"get_device_info\"}");all(s,&f);assert(provider_calls==3);assert(!contains(&f,"bootloader_migration_required"));assert(contains(&f,"\"features\":{}"));
    assert(vk_usb_service_stop(s)==ESP_OK);free(s);provider_fake=NULL;
}

static void test_voice_key_none(void){
    fake_t f={0};input_commands=0;vk_usb_service_t*s=make(&f);
    vk_usb_input_handler_registration_t registration={on_input_command,NULL};
    assert(vk_usb_service_register_input_handler(s,&registration)==ESP_OK);
    assert(vk_usb_service_start(s)==ESP_OK);epoch(s,&f);reset_in(&f);
    frame(&f,"{\"event\":\"voice_key\",\"key\":\"none\"}");all(s,&f);
    assert(input_commands==1&&last_input_command.kind==VK_USB_INPUT_COMMAND_VOICE_KEY&&last_input_command.key==VK_USB_KEY_NONE);
    f.output_count=0;assert(vk_usb_service_send_input_state_for_epoch(s,vk_usb_service_epoch(s),VK_USB_INPUT_MODE_HOLD_TO_TALK,VK_USB_KEY_NONE)==ESP_OK);
    assert(contains(&f,"\"voice_key\":\"none\""));
    assert(vk_usb_service_stop(s)==ESP_OK);free(s);
}

static void test_zero_upload_management(void)
{
    const char *sha="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
    fake_t f={0};commands=chunks=0;vk_usb_service_t *service=make(&f);register_asset(service);
    provider_snapshot.assets.upload_max_bytes=0U;
    assert(vk_usb_service_start(service)==ESP_OK);epoch(service,&f);authorize(service,&f);
    char command[256];
    snprintf(command,sizeof(command),"{\"event\":\"vk_asset_begin\",\"transfer_id\":9,\"sha256\":\"%s\",\"total_bytes\":1,\"kind\":\"image\"}",sha);
    frame(&f,command);all(service,&f);assert(commands==0);
    reset_in(&f);frame(&f,"{\"event\":\"vk_asset_query\",\"transfer_id\":9}");all(service,&f);
    reset_in(&f);frame(&f,"{\"event\":\"vk_asset_list\",\"snapshot_id\":0,\"cursor\":0,\"limit\":1}");all(service,&f);
    snprintf(command,sizeof(command),"{\"event\":\"vk_asset_delete\",\"sha256\":\"%s\",\"expected_revision\":0}",sha);
    reset_in(&f);frame(&f,command);all(service,&f);assert(commands==2&&last_cmd.kind==VK_USB_ASSET_DELETE);
    uint8_t chunk[9]={9,0,0,0,0,0,0,0,1};reset_in(&f);frame_t(&f,VK_USB_FRAME_TYPE_ASSET_CHUNK,chunk,sizeof(chunk));all(service,&f);assert(chunks==0);
    assert(vk_usb_service_stop(service)==ESP_OK);free(service);
}

static void test_active_asset_transfer(void)
{
    const char *sha="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
    fake_t f={0};commands=chunks=0;command_result=chunk_result=ESP_OK;vk_usb_service_t*s=make(&f);register_asset(s);
    assert(vk_usb_service_start(s)==ESP_OK);epoch(s,&f);authorize(s,&f);char json[256];
    snprintf(json,sizeof(json),"{\"event\":\"vk_asset_begin\",\"transfer_id\":9,\"sha256\":\"%s\",\"total_bytes\":5,\"kind\":\"image\"}",sha);
    frame(&f,json);all(s,&f);assert(commands==1&&contains(&f,"vk_asset_ready"));
    reset_in(&f);f.output_count=0;frame(&f,json);all(s,&f);assert(commands==1&&contains(&f,"vk_asset_ready"));
    uint8_t chunk1[]={9,0,0,0,0,0,0,0,1,2,3,4};reset_in(&f);f.output_count=0;frame_t(&f,VK_USB_FRAME_TYPE_ASSET_CHUNK,chunk1,sizeof(chunk1));all(s,&f);assert(chunks==1&&last_chunk.expected_epoch!=0U&&last_chunk.snapshot_generation!=0U&&last_chunk.offset==0&&last_chunk.payload_length==4&&contains(&f,"\"next_offset\":4"));
    reset_in(&f);f.output_count=0;frame_t(&f,VK_USB_FRAME_TYPE_ASSET_CHUNK,chunk1,sizeof(chunk1));all(s,&f);assert(chunks==1&&contains(&f,"bad_offset")&&contains(&f,"\"next_offset\":4"));
    uint8_t final[]={9,0,0,0,4,0,0,0,5};chunk_result=ESP_FAIL;reset_in(&f);f.output_count=0;frame_t(&f,VK_USB_FRAME_TYPE_ASSET_CHUNK,final,sizeof(final));all(s,&f);assert(chunks==2&&contains(&f,"write_failed")&&contains(&f,"phase=chunk;esp_err=0xffffffff")&&contains(&f,"\"next_offset\":4"));
    chunk_result=ESP_OK;reset_in(&f);f.output_count=0;frame_t(&f,VK_USB_FRAME_TYPE_ASSET_CHUNK,final,sizeof(final));all(s,&f);assert(chunks==3&&contains(&f,"\"next_offset\":5"));
    snprintf(json,sizeof(json),"{\"event\":\"vk_asset_end\",\"transfer_id\":9,\"sha256\":\"%s\",\"total_bytes\":5,\"kind\":\"image\"}",sha);command_result=ESP_FAIL;reset_in(&f);f.output_count=0;frame(&f,json);all(s,&f);assert(commands==2&&contains(&f,"write_failed")&&contains(&f,"phase=end;esp_err=0xffffffff"));command_result=ESP_OK;reset_in(&f);f.output_count=0;frame(&f,json);all(s,&f);assert(commands==3&&contains(&f,"vk_asset_stored"));
    reset_in(&f);f.output_count=0;frame_t(&f,VK_USB_FRAME_TYPE_ASSET_CHUNK,final,sizeof(final));all(s,&f);assert(chunks==3&&contains(&f,"unavailable"));
    reset_in(&f);f.output_count=0;frame(&f,"{\"event\":\"vk_asset_abort\",\"transfer_id\":9}");all(s,&f);assert(commands==3&&contains(&f,"vk_asset_aborted"));
    assert(vk_usb_service_stop(s)==ESP_OK);free(s);
}

static void test_wire(void){fake_t f={0};commands=chunks=0;vk_usb_service_t*s=make(&f);register_asset(s);assert(vk_usb_service_register_update_handler(s,NULL)==ESP_ERR_INVALID_ARG);assert(vk_usb_service_start(s)==ESP_OK);epoch(s,&f);authorize(s,&f);const char*valid[]={"{\"event\":\"vk_asset_begin\",\"transfer_id\":1,\"sha256\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\",\"total_bytes\":9,\"kind\":\"image\"}","{\"event\":\"vk_asset_query\",\"transfer_id\":1}","{\"event\":\"vk_asset_end\",\"transfer_id\":1,\"sha256\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\",\"total_bytes\":9,\"kind\":\"animation\"}","{\"event\":\"vk_asset_abort\",\"transfer_id\":1}","{\"event\":\"vk_asset_list\",\"snapshot_id\":1,\"cursor\":4294967295,\"limit\":64}","{\"event\":\"vk_asset_delete\",\"sha256\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\",\"expected_revision\":0}"};for(size_t i=0;i<6;++i){reset_in(&f);frame(&f,valid[i]);all(s,&f);}assert(commands==4&&last_cmd.kind==VK_USB_ASSET_DELETE);const char*invalid[]={"{\"event\":\"vk_asset_query\",\"transfer_id\":0}","{\"event\":\"vk_asset_list\",\"cursor\":0,\"limit\":65}","{\"event\":\"vk_asset_query\",\"transfer_id\":1,\"extra\":0}","{\"event\":\"vk_asset_begin\",\"transfer_id\":4294967296,\"sha256\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\",\"total_bytes\":1,\"kind\":\"image\"}","{\"event\":\"vk_asset_begin\",\"transfer_id\":1,\"sha256\":\"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"total_bytes\":1,\"kind\":\"image\"}","{\"event\":\"vk_update_begin\",\"transfer_id\":1,\"size\":1,\"sha256\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\"}" };for(size_t i=0;i<6;++i){reset_in(&f);frame(&f,invalid[i]);all(s,&f);}assert(commands==4);uint8_t b[13]={1,0,0,0,0,0,0,0,1,2,3,4,5};for(size_t n=8;n<=13;++n){reset_in(&f);frame_t(&f,0x40,b,n);all(s,&f);}assert(chunks==0);reset_in(&f);frame_t(&f,0x41,b,9);all(s,&f);assert(chunks==0);assert(vk_usb_service_stop(s)==ESP_OK);free(s);}

typedef struct{pthread_mutex_t mutex;pthread_cond_t condition;bool reached,released;} barrier_t;static void before_commit(void*c){barrier_t*b=c;assert(pthread_mutex_lock(&b->mutex)==0);b->reached=true;assert(pthread_cond_broadcast(&b->condition)==0);while(!b->released)assert(pthread_cond_wait(&b->condition,&b->mutex)==0);assert(pthread_mutex_unlock(&b->mutex)==0);}typedef struct{vk_usb_service_t*s;esp_err_t result;} one_poll_t;static void*poll_once(void*c){one_poll_t*x=c;x->result=vk_usb_service_poll(x->s);return NULL;}static void wait_barrier(barrier_t*b){assert(pthread_mutex_lock(&b->mutex)==0);while(!b->reached)assert(pthread_cond_wait(&b->condition,&b->mutex)==0);assert(pthread_mutex_unlock(&b->mutex)==0);}static void release_barrier(barrier_t*b){assert(pthread_mutex_lock(&b->mutex)==0);b->released=true;assert(pthread_cond_broadcast(&b->condition)==0);assert(pthread_mutex_unlock(&b->mutex)==0);}
static void test_dequeue_overflow_priority(void){fake_t f={0};vk_usb_service_t*s=make(&f);assert(vk_usb_service_start(s)==ESP_OK);epoch(s,&f);reset_in(&f);f.output_count=0;vk_usb_button_event_t button={.kind=VK_USB_BUTTON_CLICK,.key=VK_USB_KEY_K1};for(unsigned i=0;i<VK_USB_TYPED_TX_QUEUE_CAPACITY;i++)assert(vk_usb_service_send_button(s,&button)==ESP_OK);barrier_t b={.mutex=PTHREAD_MUTEX_INITIALIZER,.condition=PTHREAD_COND_INITIALIZER};vk_usb_service_set_before_tx_commit_hook_for_test(s,before_commit,&b);one_poll_t p={.s=s};pthread_t thread;assert(pthread_create(&thread,NULL,poll_once,&p)==0);wait_barrier(&b);assert(vk_usb_service_send_button(s,&button)==ESP_OK);assert(vk_usb_service_send_button(s,&button)==ESP_ERR_NO_MEM);release_barrier(&b);assert(pthread_join(thread,NULL)==0);assert(p.result==ESP_OK);assert(contains(&f,"control_queue_overflow"));assert(!contains(&f,"button_click"));vk_usb_service_set_before_tx_commit_hook_for_test(s,NULL,NULL);assert(vk_usb_service_stop(s)==ESP_OK);free(s);}
static size_t decode_frame(const uint8_t *bytes,size_t count,size_t offset,uint8_t *type,const uint8_t **body,size_t *length){assert(offset+4U<=count);assert(bytes[offset]==VK_USB_PROTOCOL_VERSION);*type=bytes[offset+1];*length=(size_t)bytes[offset+2]|((size_t)bytes[offset+3]<<8U);assert(offset+4U+*length<=count);*body=bytes+offset+4U;return offset+4U+*length;}
static void assert_json_frame(fake_t*f,const char*expected){uint8_t type;const uint8_t*body;size_t length;size_t end=decode_frame(f->output,f->output_count,0,&type,&body,&length);assert(type==VK_USB_FRAME_TYPE_JSON);assert(length==strlen(expected));assert(memcmp(body,expected,length)==0);assert(end==f->output_count);}
static void init_barrier(barrier_t*b){assert(pthread_mutex_init(&b->mutex,NULL)==0);assert(pthread_cond_init(&b->condition,NULL)==0);b->reached=false;b->released=false;}
static void test_audio_dequeue_overflow_priority(void){fake_t f={0};vk_usb_service_t*s=make(&f);assert(vk_usb_service_start(s)==ESP_OK);epoch(s,&f);reset_in(&f);f.output_count=0;uint8_t payload=0x5a;vk_usb_audio_frame_t a={.session_id=7,.sequence=11,.flags=1,.payload=&payload,.payload_length=1};for(unsigned i=0;i<VK_USB_TYPED_TX_QUEUE_CAPACITY;i++)assert(vk_usb_service_send_audio(s,&a)==ESP_OK);barrier_t b;init_barrier(&b);vk_usb_service_set_before_tx_commit_hook_for_test(s,before_commit,&b);one_poll_t p={.s=s};pthread_t thread;assert(pthread_create(&thread,NULL,poll_once,&p)==0);wait_barrier(&b);assert(vk_usb_service_send_audio(s,&a)==ESP_OK);assert(vk_usb_service_send_audio(s,&a)==ESP_ERR_NO_MEM);vk_usb_audio_frame_t other=a;other.session_id=8;assert(vk_usb_service_send_audio(s,&other)==ESP_ERR_INVALID_STATE);release_barrier(&b);assert(pthread_join(thread,NULL)==0);assert(p.result==ESP_OK);assert_json_frame(&f,"{\"event\":\"vk_error\",\"operation\":\"audio\",\"code\":\"audio_queue_overflow\",\"session_id\":7}");poll(s);assert(vk_usb_service_tx_queue_count_for_test(s)==0);assert(f.output_count>0);vk_usb_service_set_before_tx_commit_hook_for_test(s,NULL,NULL);assert(vk_usb_service_stop(s)==ESP_OK);free(s);}
static void test_terminal_write_failures(void){for(unsigned partial=0;partial<2;++partial){fake_t f={0};vk_usb_service_t*s=make(&f);assert(vk_usb_service_start(s)==ESP_OK);epoch(s,&f);reset_in(&f);f.output_count=0;vk_usb_button_event_t button={.kind=VK_USB_BUTTON_CLICK,.key=VK_USB_KEY_K1};for(unsigned i=0;i<VK_USB_TYPED_TX_QUEUE_CAPACITY;i++)assert(vk_usb_service_send_button(s,&button)==ESP_OK);assert(vk_usb_service_send_button(s,&button)==ESP_ERR_NO_MEM);if(partial==0)f.write_mode=-1;else{f.write_limit=5;f.write_fail_after=2;}assert(vk_usb_service_poll(s)==ESP_FAIL);if(partial==0)assert(f.output_count==0);else{assert(f.output_count==5);assert(f.output[0]==1&&f.output[1]==VK_USB_FRAME_TYPE_JSON);size_t declared=(size_t)f.output[2]|((size_t)f.output[3]<<8U);assert(f.output_count<declared+4U);}f.write_mode=0;f.write_fail_after=0;assert(vk_usb_service_stop(s)==ESP_OK);assert(f.uninstall_count==1);free(s);}}
