static void test_every_split_and_recovery(void){uint8_t body[4092];memset(body,' ',sizeof(body));memcpy(body,"{\"event\":\"x\"}",13);for(size_t split=1;split<=4096;++split){fake_t f={.read_limit=split};vk_usb_service_t*s=make(&f);assert(vk_usb_service_start(s)==ESP_OK);frame_t(&f,0x10,body,sizeof(body));frame(&f,"{\"event\":\"transport\",\"kind\":\"usb\"}");all(s,&f);assert(vk_usb_service_has_epoch(s));assert(vk_usb_service_stop(s)==ESP_OK);free(s);}const char*cap="{\"event\":\"vk_capabilities\",\"protocol\":1,\"display\":{\"width\":428,\"height\":142,\"format\":\"rgb565\"},\"features\":{}}";for(size_t split=1;split<=strlen(cap)+4;++split){fake_t f={.read_limit=split};vk_usb_service_t*s=make(&f);assert(vk_usb_service_start(s)==ESP_OK);epoch(s,&f);reset_in(&f);frame(&f,"{\"event\":\"get_device_info\"}");all(s,&f);assert(contains(&f,cap));assert(vk_usb_service_stop(s)==ESP_OK);free(s);}fake_t f={.read_limit=17};vk_usb_service_t*s=make(&f);assert(vk_usb_service_start(s)==ESP_OK);for(size_t i=0;i<6000;i++)f.input[f.input_count++]=0x55;frame(&f,"{\"event\":\"transport\",\"kind\":\"usb\"}");all(s,&f);assert(vk_usb_service_has_epoch(s));assert(vk_usb_service_stop(s)==ESP_OK);free(s);}

typedef struct{vk_usb_service_t*s;atomic_bool*run;} concurrent_t;static void*concurrent_poll(void*c){concurrent_t*x=c;while(atomic_load(x->run)){esp_err_t e=vk_usb_service_poll(x->s);if(e==ESP_ERR_INVALID_STATE)break;assert(e==ESP_OK);}return NULL;}static void*concurrent_produce(void*c){concurrent_t*x=c;uint32_t n=0;while(atomic_load(x->run)){vk_usb_button_event_t b={.kind=VK_USB_BUTTON_CLICK,.key=(vk_usb_key_t)(n++%4)};esp_err_t e=vk_usb_service_send_button(x->s,&b);assert(e==ESP_OK||e==ESP_ERR_NO_MEM||e==ESP_ERR_INVALID_STATE);}return NULL;}static void test_concurrent_owner_expiry_stop(void){fake_t f={0};vk_usb_service_t*s=make(&f);assert(vk_usb_service_start(s)==ESP_OK);epoch(s,&f);reset_in(&f);atomic_bool run=true;concurrent_t c={s,&run};pthread_t consumer,producers[3];assert(pthread_create(&consumer,NULL,concurrent_poll,&c)==0);for(size_t i=0;i<3;i++)assert(pthread_create(&producers[i],NULL,concurrent_produce,&c)==0);for(size_t i=0;i<10000;i++){(void)vk_usb_service_epoch(s);}atomic_store(&f.now_ms,VK_USB_LEASE_MS);atomic_store(&run,false);assert(pthread_join(consumer,NULL)==0);assert(vk_usb_service_stop(s)==ESP_OK);for(size_t i=0;i<3;i++)assert(pthread_join(producers[i],NULL)==0);assert(f.locks==0);free(s);}

static void test_update_disabled(void){
    update_commands=update_chunks=0;tuple_available=true;fake_t f={0};
    vk_usb_service_t*s=make_policy(&f,true);register_update_rejected(s);
    assert(vk_usb_service_start(s)==ESP_OK);epoch(s,&f);reset_in(&f);
    frame(&f,"{\"event\":\"vk_update_query\",\"transfer_id\":1}");all(s,&f);
    uint8_t chunk[9]={1,0,0,0,0,0,0,0,1};reset_in(&f);frame_t(&f,VK_USB_FRAME_TYPE_UPDATE_CHUNK,chunk,sizeof(chunk));all(s,&f);
    assert(update_commands==0&&update_chunks==0);assert(vk_usb_service_stop(s)==ESP_OK);free(s);
}

static void test_exact_typed_boundaries(void){
    const char*sha="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
    fake_t f={0};commands=chunks=0;vk_usb_service_t*s=make(&f);register_asset(s);assert(vk_usb_service_start(s)==ESP_OK);epoch(s,&f);authorize(s,&f);
    char command[256];snprintf(command,sizeof(command),"{\"event\":\"vk_asset_begin\",\"transfer_id\":9,\"sha256\":\"%s\",\"total_bytes\":1000,\"kind\":\"image\"}",sha);reset_in(&f);frame(&f,command);all(s,&f);assert(commands==1);assert(last_cmd.kind==VK_USB_ASSET_BEGIN&&last_cmd.transfer_id==9&&last_cmd.total_bytes==1000&&strcmp(last_cmd.sha256,sha)==0&&strcmp(last_cmd.asset_kind,"image")==0);
    snprintf(command,sizeof(command),"{\"event\":\"vk_asset_begin\",\"transfer_id\":9,\"sha256\":\"%s\",\"total_bytes\":1001,\"kind\":\"image\"}",sha);reset_in(&f);frame(&f,command);all(s,&f);assert(commands==1);
    const size_t payloads[]={0,1,4,5};for(size_t ci=0;ci<4;++ci){uint8_t body[13]={9,0,0,0,0x78,0x56,0x34,0x12,0xaa,0xbb,0xcc,0xdd,0xee};int before=chunks;reset_in(&f);frame_t(&f,VK_USB_FRAME_TYPE_ASSET_CHUNK,body,8+payloads[ci]);all(s,&f);assert(chunks==before);}
    uint8_t zero[9]={0};zero[8]=1;int before=chunks;reset_in(&f);frame_t(&f,VK_USB_FRAME_TYPE_ASSET_CHUNK,zero,sizeof(zero));all(s,&f);assert(chunks==before);reset_in(&f);frame_t(&f,VK_USB_FRAME_TYPE_UPDATE_CHUNK,(uint8_t[]){9,0,0,0,0,0,0,0,1},9);all(s,&f);assert(chunks==before);assert(vk_usb_service_stop(s)==ESP_OK);free(s);

    fake_t u={0};update_commands=update_chunks=0;s=make_policy(&u,true);register_update_rejected(s);
    assert(vk_usb_service_start(s)==ESP_OK);epoch(s,&u);
    reset_in(&u);frame(&u,"{\"event\":\"vk_update_query\",\"transfer_id\":7}");all(s,&u);
    uint8_t update_body[9]={7,0,0,0,0,0,0,0,1};reset_in(&u);frame_t(&u,VK_USB_FRAME_TYPE_UPDATE_CHUNK,update_body,sizeof(update_body));all(s,&u);
    assert(update_commands==0&&update_chunks==0);assert(vk_usb_service_stop(s)==ESP_OK);free(s);
}
static void test_exact_fifo_partial_write_order(void){fake_t f={.write_limit=3};vk_usb_service_t*s=make(&f);assert(vk_usb_service_start(s)==ESP_OK);epoch(s,&f);reset_in(&f);f.output_count=0;vk_usb_button_event_t buttons[]={{.kind=VK_USB_BUTTON_DOWN,.key=VK_USB_KEY_K1,.has_session_id=true,.session_id=10},{.kind=VK_USB_BUTTON_UP,.key=VK_USB_KEY_K2,.has_duration_ms=true,.duration_ms=20},{.kind=VK_USB_BUTTON_CLICK,.key=VK_USB_KEY_K4,.has_session_id=true,.session_id=30,.has_duration_ms=true,.duration_ms=40}};const char*json[]={"{\"event\":\"button_down\",\"button\":\"k1\",\"session_id\":10}","{\"event\":\"button_up\",\"button\":\"k2\",\"duration_ms\":20}","{\"event\":\"button_click\",\"button\":\"k4\",\"session_id\":30,\"duration_ms\":40}"};for(size_t i=0;i<3;++i)assert(vk_usb_service_send_button(s,&buttons[i])==ESP_OK);uint8_t payload[]={0x11,0x22};vk_usb_audio_frame_t audio={.session_id=50,.sequence=60,.flags=3,.payload=payload,.payload_length=2};assert(vk_usb_service_send_audio(s,&audio)==ESP_OK);for(size_t i=0;i<4;++i)poll(s);size_t offset=0;for(size_t i=0;i<3;++i){uint8_t type;const uint8_t*body;size_t length;offset=decode_frame(f.output,f.output_count,offset,&type,&body,&length);assert(type==VK_USB_FRAME_TYPE_JSON&&length==strlen(json[i])&&memcmp(body,json[i],length)==0);}assert(offset+18U==f.output_count);const uint8_t*audio_bytes=f.output+offset;assert(audio_bytes[0]==VK_USB_PROTOCOL_VERSION&&audio_bytes[1]==VK_USB_FRAME_TYPE_AUDIO&&audio_bytes[2]==0x10&&audio_bytes[3]==0);assert(audio_bytes[4]==50&&audio_bytes[8]==60&&audio_bytes[12]==3&&audio_bytes[14]==2&&audio_bytes[15]==0&&audio_bytes[16]==0x11&&audio_bytes[17]==0x22);offset+=18U;assert(offset==f.output_count);assert(vk_usb_service_stop(s)==ESP_OK);free(s);}
static void test_hostile_declared_length_progress_corpus(void){const char*t="{\"event\":\"transport\",\"kind\":\"usb\"}";uint8_t valid[64]={1,0x10,(uint8_t)strlen(t),0};memcpy(valid+4,t,strlen(t));const uint16_t lengths[]={0,1,255,4092,4093,4095,65535};for(size_t li=0;li<sizeof(lengths)/sizeof(*lengths);++li){for(size_t prefix=0;prefix<32;++prefix){fake_t f={0};vk_usb_service_t*s=make(&f);assert(vk_usb_service_start(s)==ESP_OK);uint8_t hostile[96];memset(hostile,0x55,sizeof(hostile));for(size_t i=0;i<prefix;++i)hostile[i]=(uint8_t)(i%3==0?1:0x55);hostile[prefix]=1;hostile[prefix+1]=0x10;hostile[prefix+2]=(uint8_t)lengths[li];hostile[prefix+3]=(uint8_t)(lengths[li]>>8);size_t n=prefix+4U;if(lengths[li]<=8U){memset(hostile+n,0x55,lengths[li]);n+=lengths[li];}size_t bytes0=vk_usb_service_consume_bytes_for_test(s),steps0=vk_usb_service_parser_steps_for_test(s);assert(vk_usb_service_consume_for_test(s,hostile,n)==ESP_OK);size_t bytes1=vk_usb_service_consume_bytes_for_test(s),steps1=vk_usb_service_parser_steps_for_test(s);assert(bytes1-bytes0==n);assert(steps1>=steps0&&steps1-steps0<=n+4U);assert(vk_usb_service_consume_for_test(s,valid,strlen(t)+4)==ESP_OK);size_t bytes2=vk_usb_service_consume_bytes_for_test(s),steps2=vk_usb_service_parser_steps_for_test(s);assert(bytes2-bytes1==strlen(t)+4U);assert(steps2>=steps1&&steps2-steps1<=strlen(t)+8U);if(lengths[li]>VK_USB_MAX_JSON_BYTES||lengths[li]<=8U)assert(vk_usb_service_has_epoch(s));assert(vk_usb_service_stop(s)==ESP_OK);free(s);}}}
static void test_hostile_saturation_fragment_layouts(void){const char*t="{\"event\":\"transport\",\"kind\":\"usb\"}";uint8_t valid[64]={1,VK_USB_FRAME_TYPE_JSON,(uint8_t)strlen(t),0};memcpy(valid+4,t,strlen(t));const uint16_t lengths[]={1,255,4092,4093,65535};const size_t fills[]={VK_USB_MAX_FRAME_BYTES-3U,VK_USB_MAX_FRAME_BYTES,VK_USB_MAX_FRAME_BYTES+17U};const size_t fragments[]={1,17,257};for(size_t li=0;li<5;++li)for(size_t fi=0;fi<3;++fi)for(size_t gi=0;gi<3;++gi){fake_t f={0};vk_usb_service_t*s=make(&f);assert(vk_usb_service_start(s)==ESP_OK);size_t total=4U+fills[fi];uint8_t*hostile=malloc(total);assert(hostile);memset(hostile+4,0x55,fills[fi]);hostile[0]=1;hostile[1]=VK_USB_FRAME_TYPE_JSON;hostile[2]=(uint8_t)lengths[li];hostile[3]=(uint8_t)(lengths[li]>>8U);size_t offset=0,previous_bytes=0,previous_steps=0;while(offset<total){size_t amount=fragments[gi];if(amount>total-offset)amount=total-offset;assert(vk_usb_service_consume_for_test(s,hostile+offset,amount)==ESP_OK);size_t current_bytes=vk_usb_service_consume_bytes_for_test(s),current_steps=vk_usb_service_parser_steps_for_test(s);assert(current_bytes==previous_bytes+amount);assert(current_steps>=previous_steps&&current_steps-previous_steps<=amount+4U);previous_bytes=current_bytes;previous_steps=current_steps;offset+=amount;}free(hostile);assert(vk_usb_service_consume_for_test(s,valid,strlen(t)+4U)==ESP_OK);assert(vk_usb_service_consume_bytes_for_test(s)==previous_bytes+strlen(t)+4U);assert(vk_usb_service_parser_steps_for_test(s)>=previous_steps);assert(vk_usb_service_parser_steps_for_test(s)-previous_steps<=strlen(t)+8U);assert(vk_usb_service_has_epoch(s));assert(vk_usb_service_stop(s)==ESP_OK);free(s);}}
