typedef struct { vk_usb_input_lifecycle_request_t request; vk_usb_input_lifecycle_sink_t sink; fake_t *transport; bool auto_ack; vk_usb_input_lifecycle_ack_result_t result; int calls; } lifecycle_probe_t;
static vk_usb_input_lifecycle_begin_result_t lifecycle_begin(void *context,const vk_usb_input_lifecycle_request_t *request,const vk_usb_input_lifecycle_sink_t *sink){lifecycle_probe_t*p=context;assert(p->transport==NULL||p->transport->locks==0);p->request=*request;p->sink=*sink;++p->calls;if(p->auto_ack){vk_usb_input_lifecycle_ack_t ack={request->token,request->lifecycle_generation,p->result};(void)sink->publish(sink->context,&ack);}return VK_USB_INPUT_LIFECYCLE_ACCEPTED;}
static void test_input_lifecycle_boundaries(void){
    fake_t f={0};vk_usb_service_t*s=make(&f);lifecycle_probe_t p={.transport=&f,.auto_ack=true,.result=VK_USB_INPUT_LIFECYCLE_QUIESCENT};vk_usb_input_lifecycle_registration_t r={lifecycle_begin,&p};assert(vk_usb_service_register_input_lifecycle(s,&r)==ESP_OK);assert(vk_usb_service_start(s)==ESP_OK);epoch(s,&f);assert(p.calls==1&&p.request.old_epoch==0U&&p.request.proposed_epoch!=0U);uint32_t epoch1=vk_usb_service_epoch(s);
    p.auto_ack=false;reset_in(&f);f.output_count=0;frame(&f,"{\"event\":\"transport\",\"kind\":\"usb\"}");assert(vk_usb_service_poll(s)==ESP_OK);assert(!vk_usb_service_has_epoch(s));assert(f.output_count==0);reset_in(&f);frame(&f,"{\"event\":\"get_device_info\"}");assert(vk_usb_service_poll(s)==ESP_OK);assert(f.input_offset==0&&f.output_count==0);vk_usb_input_lifecycle_ack_t wrong={p.request.token+1U,p.request.lifecycle_generation,VK_USB_INPUT_LIFECYCLE_QUIESCENT};assert(!p.sink.publish(p.sink.context,&wrong));atomic_store(&f.now_ms,3250U-1U);vk_usb_input_lifecycle_ack_t good={p.request.token,p.request.lifecycle_generation,VK_USB_INPUT_LIFECYCLE_QUIESCENT};assert(p.sink.publish(p.sink.context,&good));assert(!p.sink.publish(p.sink.context,&good));assert(vk_usb_service_process_lifecycle(s)==ESP_OK);assert(vk_usb_service_has_epoch(s)&&vk_usb_service_epoch(s)!=epoch1);all(s,&f);
    uint32_t epoch2=vk_usb_service_epoch(s);p.auto_ack=false;reset_in(&f);atomic_store(&f.now_ms,10000U);frame(&f,"{\"event\":\"transport\",\"kind\":\"usb\"}");assert(vk_usb_service_poll(s)==ESP_OK);assert(!vk_usb_service_has_epoch(s));assert(p.request.absolute_deadline_ms==10000U+1500U+1500U+250U);atomic_store(&f.now_ms,10000U+3250U);good=(vk_usb_input_lifecycle_ack_t){p.request.token,p.request.lifecycle_generation,VK_USB_INPUT_LIFECYCLE_QUIESCENT};assert(!p.sink.publish(p.sink.context,&good));assert(vk_usb_service_process_lifecycle(s)==ESP_ERR_TIMEOUT);assert(vk_usb_service_is_tainted(s));assert(!vk_usb_service_has_epoch(s));assert(vk_usb_service_epoch(s)==epoch2);free(s);
    fake_t late={0};s=make(&late);lifecycle_probe_t q={.transport=&late,.auto_ack=false,.result=VK_USB_INPUT_LIFECYCLE_QUIESCENT};r=(vk_usb_input_lifecycle_registration_t){lifecycle_begin,&q};assert(vk_usb_service_register_input_lifecycle(s,&r)==ESP_OK);assert(vk_usb_service_start(s)==ESP_OK);frame(&late,"{\"event\":\"transport\",\"kind\":\"usb\"}");assert(vk_usb_service_poll(s)==ESP_OK);assert(!vk_usb_service_has_epoch(s));atomic_store(&late.now_ms,3251U);good=(vk_usb_input_lifecycle_ack_t){q.request.token,q.request.lifecycle_generation,VK_USB_INPUT_LIFECYCLE_QUIESCENT};assert(!q.sink.publish(q.sink.context,&good));assert(vk_usb_service_process_lifecycle(s)==ESP_ERR_TIMEOUT);assert(vk_usb_service_is_tainted(s));free(s);
}
static void test_lifecycle(void){fake_t f={.uninstall_fail=true};vk_usb_service_t*s=make(&f);assert(vk_usb_service_start(s)==ESP_OK);assert(vk_usb_service_stop(s)==ESP_FAIL);assert(vk_usb_service_start(s)==ESP_ERR_INVALID_STATE);f.uninstall_fail=false;assert(vk_usb_service_stop(s)==ESP_OK);free(s);for(int m=-1;m<=2;m++){if(m==0)continue;fake_t x={.write_mode=m};s=make(&x);assert(vk_usb_service_start(s)==ESP_OK);epoch(s,&x);reset_in(&x);frame(&x,"{\"event\":\"get_device_info\"}");assert(vk_usb_service_poll(s)==ESP_FAIL);x.write_mode=0;assert(vk_usb_service_stop(s)==ESP_OK);free(s);}}
static void test_audio_epoch_handoff(void){fake_t f={0};vk_usb_service_t*s=make(&f);assert(vk_usb_service_start(s)==ESP_OK);epoch(s,&f);uint32_t current=vk_usb_service_epoch(s);uint8_t payload=0x5a;vk_usb_audio_frame_t a={.session_id=7,.sequence=0,.flags=1,.payload=&payload,.payload_length=1};assert(current!=0U);assert(vk_usb_service_send_audio_for_epoch(s,current,&a)==ESP_OK);assert(vk_usb_service_send_audio_for_epoch(s,current+1U,&a)==ESP_ERR_INVALID_STATE);assert(vk_usb_service_send_audio_for_epoch(s,0U,&a)==ESP_ERR_INVALID_ARG);assert(vk_usb_service_stop(s)==ESP_OK);free(s);pthread_mutex_destroy(&f.mutex);}
int main(void){test_input_lifecycle_boundaries();test_provider_lifetime_stop();test_capability_provider();test_voice_key_none();test_zero_upload_management();test_active_asset_transfer();test_audio_epoch_handoff();test_unicode();test_wire();test_exact_typed_boundaries();test_exact_fifo_partial_write_order();test_dequeue_overflow_priority();test_audio_dequeue_overflow_priority();test_terminal_write_failures();test_barrier_expiry_epoch_and_stop();test_pending_audio_terminal_rejects_other_session();test_queue();test_every_split_and_recovery();test_hostile_declared_length_progress_corpus();test_hostile_saturation_fragment_layouts();test_exact_splits_and_declared_progress();test_update_disabled();test_concurrent_owner_expiry_stop();test_lifecycle();puts("vk_usb native tests passed");}
